import{I as i,o as g,c as v,j as e,a as n,J as t,w as r,b6 as a,cN as b,cO as f,cP as h,cQ as q,cR as x,cS as y,cT as A,cU as I,cV as _,cW as k,cX as z,cY as P,cZ as C,c_ as E,c$ as S,d0 as D,d1 as T,d2 as j,d3 as V,k as L}from"./chunks/framework.BUXTSoD9.js";import{r as R}from"./chunks/relatedArticles.DIHQAH-1.js";const N={style:{margin:"50px 0"}},Q={style:{margin:"50px 0"}},M={style:{margin:"50px 0"}},O={style:{margin:"50px 0"}},J=JSON.parse(`{"title":"Créer votre prototype : de l'analyse métier au prototype produit multi-pages","description":"Vivre le cycle complet de l'analyse métier à la réalisation d'un prototype produit multi-pages. Apprendre à poser des questions métier, décomposer les besoins, utiliser l'IDE AI pour générer des applications mono-page et multi-pages, et peaufiner et tester les prototypes.","frontmatter":{"title":"Créer votre prototype : de l'analyse métier au prototype produit multi-pages","description":"Vivre le cycle complet de l'analyse métier à la réalisation d'un prototype produit multi-pages. Apprendre à poser des questions métier, décomposer les besoins, utiliser l'IDE AI pour générer des applications mono-page et multi-pages, et peaufiner et tester les prototypes."},"headers":[],"relativePath":"fr-fr/stage-1/building-prototype/index.md","filePath":"fr-fr/stage-1/building-prototype/index.md"}`),U={name:"fr-fr/stage-1/building-prototype/index.md"},W=Object.assign(U,{setup(w){const p="Environ <strong>8 heures</strong>",d=R["fr-fr/stage-1/building-prototype"]??[];return(F,s)=>{const c=i("ChapterIntroduction"),o=i("StepBar"),l=i("ClientOnly"),u=i("el-card"),m=i("RelatedArticlesSection");return g(),v("div",null,[s[5]||(s[5]=e("h1",{id:"niveau-debutant-3-creer-votre-prototype",tabindex:"-1"},[n("Niveau débutant 3 : Créer votre prototype "),e("a",{class:"header-anchor",href:"#niveau-debutant-3-creer-votre-prototype","aria-label":"Permalink to “Niveau débutant 3 : Créer votre prototype”"},"​")],-1)),s[6]||(s[6]=e("h2",{id:"introduction-du-chapitre",tabindex:"-1"},[n("Introduction du chapitre "),e("a",{class:"header-anchor",href:"#introduction-du-chapitre","aria-label":"Permalink to “Introduction du chapitre”"},"​")],-1)),t(c,{duration:p,tags:["Analyse métier","Conception de prototype","Programmation assistée par AI","Applications multi-pages"],coreOutput:"1 prototype d'atelier de contenus e-commerce",expectedOutput:"Prototype Web interactif"},{default:r(()=>[...s[0]||(s[0]=[e("p",null,[n("Dans le chapitre précédent, nous avons appris à "),e("strong",null,"trouver de bonnes idées"),n(" — partir des besoins utilisateurs pour trouver des directions pour lesquelles quelqu'un est prêt à payer. Mais trouver la direction n'est que la première étape, "),e("strong",null,"ce qui met vraiment à l'épreuve le chef de produit, c'est : comment transformer des besoins flous en un produit utilisable.")],-1),e("p",null,[n("Ce chapitre va résoudre un "),e("strong",null,"problème réel"),n(" : votre patron vous lance un « utilise l'IA pour améliorer l'efficacité de la publication de produits sur les plateformes e-commerce » — comment transformer ça en un "),e("strong",null,"prototype produit fonctionnel"),n(" ?")],-1),e("p",null,[n("Contrairement aux jeux Snake et calculatrices précédents, "),e("strong",null,"dans les vrais projets on ne peut pas inventer les fonctionnalités"),n(" :")],-1),e("ol",null,[e("li",null,[e("strong",null,"Identifier les points de douleur"),n(" : discuter avec les opérationnels, extraire des "),e("strong",null,"vrais points de douleur"),n(" du vague « améliorer l'efficacité »")]),e("li",null,[e("strong",null,"Prioriser"),n(" : parmi tous les problèmes, résoudre d'abord "),e("strong",null,"le plus douloureux"),n(", sans vouloir tout faire d'un coup")]),e("li",null,[e("strong",null,"Valider rapidement"),n(" : utiliser l'IDE AI pour d'abord faire un "),e("strong",null,"prototype mono-page"),n(", puis étendre en multi-pages une fois que ça fonctionne")]),e("li",null,[e("strong",null,"Produire quelque chose d'utilisable"),n(" : livrer finalement un "),e("strong",null,"atelier de contenus e-commerce démontrable et utilisable")])],-1),e("p",null,[n("Nous apprendrons la transition de "),e("strong",null,"faire des jouets à faire des applications"),n(", et à "),e("strong",null,"empathiser et réfléchir aux vrais besoins des clients"),n(".")],-1)])]),_:1}),s[7]||(s[7]=e("div",{class:"info custom-block"},[e("p",{class:"custom-block-title"},"ℹ️ Note"),e("p",null,"Ce chapitre peut contenir des termes métier que vous ne connaissez pas — vous pouvez demander à l'IA de vous les expliquer.")],-1)),e("div",N,[t(l,null,{default:r(()=>[t(o,{active:0,items:[{title:"Analyse des besoins",description:"Du flou au concret"},{title:"Validation mono-page",description:"Fonctionnalité clé implémentée"},{title:"Extension multi-pages",description:"Structure d'application complète"},{title:"Peaufinage",description:"Amélioration de l'expérience utilisateur"}]})]),_:1})]),s[8]||(s[8]=a('<h2 id="_1-definir-les-besoins-avant-de-coder" tabindex="-1">1. Définir les besoins avant de coder <a class="header-anchor" href="#_1-definir-les-besoins-avant-de-coder" aria-label="Permalink to “1. Définir les besoins avant de coder”">​</a></h2><p>Dans les tutoriels précédents, nous avons utilisé l&#39;IDE AI pour générer facilement des jeux Snake et autres petits jeux, mais ce ne sont que des projets ludiques qui ne peuvent pas être appliqués au travail et à la vie quotidienne ; si nous voulons que les capacités AI soient véritablement utiles à tous, nous devons faire du Vibe Coding en combinant des scénarios de vie et de travail.</p><p>Dans le chapitre précédent, nous avons appris à trouver des <strong>bonnes idées pour lesquelles quelqu&#39;un est prêt à payer</strong>, mais trouver une direction n&#39;est que le début. Quand on fait vraiment un produit, on découvre que : <strong>il y a un énorme fossé entre savoir « quoi faire » et savoir « comment le faire ».</strong></p><p>Ce fossé, c&#39;est la <strong>spécification des besoins</strong>.</p><p>Par exemple, dans un projet de classe ou personnel, on part souvent de la fonctionnalité exécutable la plus simple pour faire un produit ou une application :</p><ul><li>« Fais un tableau Kanban, liste les tâches. »</li><li>« Aide-moi à faire un outil de dessin. »</li><li>« Aide-moi à faire un logiciel pour collecter des questionnaires. »</li></ul><p>Ce ne sont souvent qu&#39;un outil, un module fonctionnel, et même pas un problème métier clair. Plus important encore, <strong>ces idées sont souvent « ce que tu trouves utile » et non « ce dont l&#39;utilisateur a vraiment besoin ».</strong></p><p>Dans les projets d&#39;entreprise ou de startup, les chefs de produit et les ingénieurs partent souvent d&#39;une proposition métier plus large. Par exemple, nous pouvons imaginer le scénario suivant :</p>',8)),t(u,{shadow:"hover",style:{"border-left":"5px solid #409EFF","background-color":"#ecf5ff",margin:"20px 0"}},{default:r(()=>[...s[1]||(s[1]=[e("div",{style:{"font-weight":"bold",color:"#303133","margin-bottom":"10px"}},"🛍️ Scénario métier :",-1),e("div",{style:{color:"#606266","line-height":"1.6"}},[e("p",null,"Vous êtes chef de produit e-commerce dans une boutique. Le patron vous donne une proposition vague mais stressante :"),e("p",{style:{"font-style":"italic","margin-top":"10px"}},"« Maintenant tout le monde utilise l'IA pour faire des images et des textes sur les réseaux sociaux, ça a l'air simple. Aide-moi à mettre ça en place pour qu'on soit plus efficace quand on met de nouveaux produits sur TikTok Shop. »")],-1)])]),_:1}),s[9]||(s[9]=a(`<p>À ce moment-là, vous pourriez penser : « Patron, tu rêves encore ! » Pourtant, dans le monde réel, ce genre de décision vague en une phrase est très courant — même plus fréquent que le nombre de bubble tea que vous commandez en une semaine. Donc, pour devenir un bon professionnel (ou mieux, le CEO d&#39;une nouvelle startup), nous devons apprendre à passer de la création d&#39;outils personnels à la création de vrais prototypes produits.</p><p>Puisque nous avons appris l&#39;IDE AI, en y réfléchissant bien, ce besoin est assez simple — il suffit de donner un prompt à l&#39;IA et de laisser l&#39;Agent s&#39;occuper de tout, non ?</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Merci de te référer à mon besoin xxxx,</span></span>
<span class="line"><span>aide-moi à concevoir un atelier de contenus e-commerce,</span></span>
<span class="line"><span>incluant la génération et la gestion de descriptions produits, images, vidéos et autres contenus.</span></span></code></pre></div><p>Si vous transformez joyeusement ce besoin en prototype et l&#39;envoyez au patron — félicitations, votre bonus de ce trimestre est annulé !</p><p><strong>Pourquoi ? C&#39;est le point de douleur central que nous devons résoudre :</strong></p><p>Quand nous avons appris l&#39;IDE AI, nous faisions des <strong>projets ludiques personnels</strong> comme Snake ou une calculatrice — fonctionnalités simples, on sait ce qu&#39;on veut, et on fait pour soi. Mais <strong>les vrais scénarios métier sont complètement différents</strong> :</p><ul><li><strong>Vous n&#39;êtes pas l&#39;utilisateur</strong> : le patron veut « améliorer l&#39;efficacité », mais vous ne savez pas comment les opérationnels travaillent au quotidien ni où ils bloquent ;</li><li><strong>L&#39;IA ne comprend pas le métier</strong> : vous donnez un besoin vague à l&#39;IA, elle ne peut que deviner à partir de connaissances générales, et le résultat peut ressembler à quelque chose mais être inutilisable en pratique ;</li><li><strong>Une bonne idée n&#39;est pas un bon produit</strong> : vous trouvez peut-être que « ajouter une fonctionnalité de génération AI » est cool, mais les utilisateurs pourraient ne pas en avoir besoin, ou l&#39;utiliser pourrait être plus compliqué qu&#39;avant.</li></ul><p><strong>C&#39;est pourquoi nous devons apprendre à « passer de l&#39;idée à la compréhension utilisateur »</strong>. Ce n&#39;est que lorsque votre idée résout vraiment le problème des autres, en posant des questions et en comprenant le métier en profondeur, que vous pourrez créer quelque chose de véritablement précieux. (Une bonne idée peut même être plus importante que la bonne technique.)</p><h3 id="_1-1-de-l-imaginaire-au-reel-apprendre-a-poser-des-questions-metier" tabindex="-1">1.1 De l&#39;imaginaire au réel : apprendre à poser des questions métier <a class="header-anchor" href="#_1-1-de-l-imaginaire-au-reel-apprendre-a-poser-des-questions-metier" aria-label="Permalink to “1.1 De l&#39;imaginaire au réel : apprendre à poser des questions métier”">​</a></h3><div class="info custom-block"><p class="custom-block-title">💡 D&#39;abord, clarifions : qu&#39;est-ce qu&#39;un besoin ? Qu&#39;est-ce que le métier ?</p><p>Un <strong>besoin</strong> (requirement), c&#39;est ce que l&#39;utilisateur veut vraiment, le problème qu&#39;il rencontre, la chose qu&#39;il veut résoudre. Par exemple, « le patron veut que je mette les produits en ligne plus vite » — c&#39;est un besoin.</p><p>Le <strong>métier</strong> (business), c&#39;est ce que l&#39;utilisateur fait réellement chaque jour, sa façon de travailler. Par exemple, un opérationnel e-commerce fait chaque jour : mettre des produits en ligne, modifier les prix, créer des images, analyser les données... tout ça, c&#39;est le métier.</p><p><strong>Pourquoi s&#39;intéresser au métier ?</strong> Parce que si vous ne comprenez pas le métier, l&#39;outil que vous créerez risque d&#39;être « beau mais inutilisé ». Ce n&#39;est qu&#39;en comprenant vraiment comment les utilisateurs travaillent au quotidien et où ils bloquent que vous pourrez créer quelque chose qui les aide vraiment.</p></div><p>En partant de la perspective la plus simple, vous pouvez d&#39;abord vous poser quelques questions :</p><ul><li>Quand le patron dit « <strong>efficacité améliorée</strong> », qu&#39;est-ce que ça veut dire exactement ? Faire les choses <strong>plus vite</strong> ? <strong>Dépenser moins</strong> ? <strong>Vendre plus</strong> ?</li><li>Comment sont mis en ligne les produits actuellement ? <strong>Où ça coince</strong> ?</li><li>Combien de <strong>nouveaux produits</strong> faut-il traiter chaque jour ? Combien d&#39;<strong>images</strong> et combien de <strong>textes</strong> par produit ?</li><li>Dans le travail actuel, <strong>quelle est la tâche la plus pénible</strong>, celle qu&#39;on <strong>aimerait le plus éviter</strong> ?</li></ul><p>Mais ce sont toutes des questions spéculatives. Nous devons poser directement des questions aux opérationnels TikTok Shop : « Quelles sont vos difficultés et vos points d&#39;attention ? » pour obtenir des réponses plus précises par la communication :</p><div class="info custom-block"><p class="custom-block-title">📋 Résultats d&#39;entretien métier réel</p><p>Nous avons demandé à des personnes faisant de l&#39;e-commerce, voici leurs frustrations :</p><p><strong>1. Trop de choses à faire, trop dispersées</strong></p><ul><li>Une personne gère plusieurs boutiques, chacune avec beaucoup de produits à traiter ;</li><li>Chaque jour c&#39;est la course : <strong>mise en ligne de nouveaux produits</strong>, <strong>modification de prix</strong>, <strong>création d&#39;images</strong>, <strong>analyse des données</strong>, une tâche pas finie qu&#39;il faut déjà passer à la suivue.</li></ul><p><strong>2. Le contenu n&#39;est pas fait en une fois, c&#39;est un processus itératif</strong></p><ul><li>On commence avec les <strong>images fournies par le fabricant</strong>, les <strong>anciens contenus</strong> ou des <strong>images de référence trouvées en ligne</strong>, pour rapidement <strong>mettre le produit en ligne</strong> et tester ;</li><li>On dépense un peu en promotion pour <strong>voir si ça vend</strong> ;</li><li>Ce n&#39;est que pour les <strong>produits qui se vendent bien</strong> qu&#39;on prend le temps de faire de vraies images, descriptions détaillées et vidéos.</li></ul></div><p>Après avoir interrogé les opérationnels, nous sommes enthousiastes, car maintenant nous pouvons vraiment créer un prototype produit parfaitement adapté au métier ! — Encore raté. Si nous essayons de « satisfaire toutes les demandes d&#39;un coup », le produit sera très volumineux et difficile à livrer dans le temps du cours. Il faut donc encore trier et converger pour identifier le vrai point de douleur central.</p><h3 id="_1-2-de-la-divergence-a-la-convergence-verrouiller-le-point-de-douleur-metier-central-et-les-fonctionnalites" tabindex="-1">1.2 De la divergence à la convergence : verrouiller le point de douleur métier central et les fonctionnalités <a class="header-anchor" href="#_1-2-de-la-divergence-a-la-convergence-verrouiller-le-point-de-douleur-metier-central-et-les-fonctionnalites" aria-label="Permalink to “1.2 De la divergence à la convergence : verrouiller le point de douleur métier central et les fonctionnalités”">​</a></h3><div class="info custom-block"><p class="custom-block-title">💡 Pourquoi « converger » ? Qu&#39;est-ce qu&#39;un « point de douleur » ?</p><p><strong>Il y a beaucoup de problèmes, mais par lequel commencer ?</strong></p><p>L&#39;utilisateur peut vous dire plein de problèmes : A est pénible, B est pénible, C est pénible... mais si vous essayez de tout résoudre en même temps, vous risquez de ne rien faire de bien. Donc il faut <strong>converger</strong> — c&#39;est-à-dire, parmi tous les problèmes, choisir celui qui est <strong>le plus douloureux, le plus urgent, le plus soluble</strong> pour commencer.</p><p><strong>Qu&#39;est-ce qu&#39;un point de douleur ?</strong> C&#39;est le problème spécifique que l&#39;utilisateur <strong>trouve le plus pénible, qui lui prend le plus de temps, qu&#39;il veut le plus résoudre</strong>. Pas « je trouve ça utile », mais la chose dont l&#39;utilisateur <strong>se plaint tous les jours, qui est douloureuse à chaque fois</strong>.</p></div><p>À travers les entretiens ci-dessus, nous avons découvert que les opérationnels rencontrent de nombreux problèmes : rythme perturbé par les promotions, gestion de plusieurs boutiques, jonglage entre mise en ligne / modification de prix / création d&#39;images / analyse de données...</p><p>Si nous essayons de « résoudre tous ces problèmes », nous finirons par créer un outil <strong>vaste mais peu utilisable</strong>.</p><p>Classons ces problèmes (l&#39;IA peut vous aider), on trouve grosso modo trois catégories :</p><ol><li><strong>Problème de rythme</strong> : quand mettre en ligne, quand ajuster les prix ;</li><li><strong>Problème d&#39;efficacité</strong> : comment gérer simultanément plusieurs boutiques et produits ;</li><li><strong>Problème de contenu</strong> : comment créer rapidement des images et textes de produits.</li></ol><p>Pour notre cours, le plus adapté à résoudre en premier est la <strong>catégorie 3 : le problème de contenu</strong>. Mais « créer du contenu rapidement » reste un peu abstrait, demandons encore aux opérationnels où ils bloquent exactement :</p><div class="info custom-block"><p class="custom-block-title">📋 Les opérationnels disent : il y a deux endroits les plus douloureux pour le contenu</p><p><strong>Douleur 1 : la création en masse d&#39;images et de textes est trop pénible</strong></p><ul><li>Les contenus sont éparpillés : cloud, messages WeChat, back-office de la plateforme... <strong>difficiles à retrouver</strong> ;</li><li>Il faut mettre en ligne beaucoup de produits d&#39;un coup, <strong>pas le temps de faire chaque chose soigneusement</strong>, on assemble à la va-vite ;</li><li>Les exigences ne sont pas élevées, <strong>ça doit être présentable et publiable</strong>, pas besoin d&#39;être magnifique.</li></ul><p><strong>Douleur 2 : les bonnes solutions ne peuvent pas être sauvegardées pour réutilisation</strong></p><ul><li>Les bons titres et mises en page d&#39;avant, <strong>la prochaine fois on ne les retrouve plus</strong> ;</li><li>Les solutions sont dispersées dans les historiques de chat, les anciens liens de produits ;</li><li>Quand on veut les utiliser, il faut <strong>chercher pendant des heures, copier-coller et modifier pendant des heures</strong> ;</li><li>Il manque un outil pour <strong>sauvegarder, gérer et appliquer directement</strong>.</li></ul></div><p>Sur la base de ces deux points de douleur, nous allons créer un petit outil simple : <strong>aider les opérationnels à créer en masse des images et textes, et permettre de sauvegarder les bonnes solutions pour les réutiliser directement la prochaine fois</strong>.</p><p>Il ne fait que deux choses (l&#39;IA peut vous aider à affiner, n&#39;oubliez pas de supprimer les fonctionnalités en fonction des retours métier) :</p><div class="info custom-block"><p class="custom-block-title">Fonctionnalité 1 : Générer en masse des images et textes de produits e-commerce</p><p><strong>À quoi ça sert ?</strong> Donner au système des informations produit, il génère automatiquement des images et textes utilisables pour la mise en ligne sur les plateformes e-commerce (comme TikTok, Taobao).</p><p><strong>Entrée</strong></p><table tabindex="0"><thead><tr><th>Type</th><th>Contenu</th></tr></thead><tbody><tr><td>Informations produit</td><td>Nom, catégorie, marque, matière, taille, couleur, etc.</td></tr><tr><td>Images produit</td><td>Image sur fond blanc ou photo en situation simple</td></tr><tr><td>Images de référence</td><td>Captures d&#39;écran de produits qui se vendent bien ou liens de référence</td></tr><tr><td>Mode d&#39;importation</td><td>Import par lot via Excel, ou saisie directe sur la page</td></tr></tbody></table><p><strong>Sortie (contenus e-commerce générés)</strong></p><ul><li><strong>Image principale</strong> : image de présentation du produit avec points de vente en texte (la première image que l&#39;utilisateur voit en scrollant)</li><li><strong>Titre du produit</strong> : combinaison de mots-clés trouvables par recherche</li><li><strong>Texte de vente</strong> : 1-2 phrases pour attirer les acheteurs</li><li>Tous des produits finis <strong>prêts à publier après quelques ajustements</strong></li></ul><p><strong>Résultat</strong></p><ul><li>Avant : chaque produit nécessite de créer des images et textes à partir de zéro</li><li>Maintenant : on envoie un lot de produits au système, on obtient des brouillons qu&#39;il suffit de sélectionner et peaufiner</li></ul></div><div class="info custom-block"><p class="custom-block-title">Fonctionnalité 2 : Sauvegarder les bonnes solutions en tant que modèles</p><p><strong>Entrée</strong></p><table tabindex="0"><thead><tr><th>Type</th><th>Contenu</th></tr></thead><tbody><tr><td>Un ensemble complet</td><td>Image principale + titre + texte</td></tr></tbody></table><p><strong>Sortie</strong></p><table tabindex="0"><thead><tr><th>Fonction</th><th>Description</th></tr></thead><tbody><tr><td>Appliquer</td><td>Utiliser le modèle pour générer automatiquement les nouveaux produits</td></tr><tr><td>Modifier</td><td>Modifier directement le titre et le texte</td></tr><tr><td>Gérer</td><td>Nommer, étiqueter (ex : « modèle sac homme », « titre promo ») pour faciliter la recherche</td></tr></tbody></table><p><strong>Résultat</strong></p><ol><li>Importer un nouveau produit</li><li>Choisir : laisser le système générer par défaut, ou <strong>utiliser mon modèle sauvegardé</strong></li><li>Le système applique automatiquement le style du modèle, et produit de nouvelles images et textes</li></ol></div><hr><p><strong>Récapitulons ce que nous venons de faire :</strong></p><ol><li><strong>D&#39;abord poser des questions</strong> : au lieu de se lancer directement, on demande d&#39;abord aux opérationnels « ce qui vous embête le plus » ;</li><li><strong>Trouver les points de douleur</strong> : on découvre que ce qu&#39;ils trouvent le plus pénible, c&#39;est « créer des images et textes est trop laborieux » et « les bonnes solutions ne peuvent pas être sauvegardées » ;</li><li><strong>Converger le périmètre</strong> : au lieu de faire une plateforme exhaustive, on se concentre sur « génération en masse d&#39;images et textes + sauvegarde de modèles », ces deux fonctionnalités uniquement.</li></ol><p><strong>Pourquoi est-ce important ?</strong></p><p>L&#39;erreur de beaucoup de débutants en produit est : plus il y a de fonctionnalités, mieux c&#39;est. Mais ce dont l&#39;utilisateur a vraiment besoin, c&#39;est qu&#39;on <strong>résolve le problème le plus douloureux</strong>. Mieux vaut faire une ou deux fonctionnalités qui aident vraiment l&#39;utilisateur, qu&#39;un tas de fonctionnalités mal faites.</p><p><strong>Le cœur de la réflexion produit et métier :</strong></p><ul><li>Ne pas imaginer « je pense que l&#39;utilisateur a besoin de ceci »</li><li>Aller demander à l&#39;utilisateur « que fais-tu chaque jour ? Où as-tu le plus mal ? »</li><li>Parmi tous les problèmes, <strong>converger</strong> vers le plus douloureux et le plus soluble</li><li>D&#39;abord créer la version <strong>minimum viable</strong>, puis itérer progressivement</li></ul><p>Voilà ce qu&#39;il faut clarifier avant de coder. Le code n&#39;est qu&#39;un outil — <strong>comprendre l&#39;utilisateur et identifier le bon problème</strong> est la première étape.</p>`,35)),e("div",Q,[t(l,null,{default:r(()=>[t(o,{active:1,items:[{title:"Analyse des besoins",description:"Du flou au concret"},{title:"Validation mono-page",description:"Fonctionnalité clé implémentée"},{title:"Extension multi-pages",description:"Structure d'application complète"},{title:"Peaufinage",description:"Amélioration de l'expérience utilisateur"}]})]),_:1})]),s[10]||(s[10]=a(`<h2 id="_2-produire-un-prototype-en-10-minutes-faire-atterrir-la-«-fonctionnalite-cle-»-avec-l-ide-ai" tabindex="-1">2. Produire un prototype en 10 minutes : faire atterrir la « fonctionnalité clé » avec l&#39;IDE AI <a class="header-anchor" href="#_2-produire-un-prototype-en-10-minutes-faire-atterrir-la-«-fonctionnalite-cle-»-avec-l-ide-ai" aria-label="Permalink to “2. Produire un prototype en 10 minutes : faire atterrir la « fonctionnalité clé » avec l&#39;IDE AI”">​</a></h2><div class="info custom-block"><p class="custom-block-title">💡 Conseil Plan de programmation</p><p>Si vous trouvez que l&#39;IDE actuel n&#39;est pas assez intelligent, ou que vous épuisez rapidement vos crédits, vous pouvez acheter un <strong>Plan de programmation</strong>. Pour anticiper, consultez <a href="./../../stage-2/backend/modern-cli/">cet article</a> sur l&#39;utilisation de Claude pour programmer.</p></div><p>Réfléchir est une bonne chose, mais il ne faut pas sur-réfléchir. Arrêtons de trop philosopher et essayons de créer un prototype en commençant par une seule page.</p><h3 id="_2-1-premiere-etape-dire-a-l-ia-ce-que-vous-voulez-en-langage-courant" tabindex="-1">2.1 Première étape : dire à l&#39;IA ce que vous voulez en langage courant <a class="header-anchor" href="#_2-1-premiere-etape-dire-a-l-ia-ce-que-vous-voulez-en-langage-courant" aria-label="Permalink to “2.1 Première étape : dire à l&#39;IA ce que vous voulez en langage courant”">​</a></h3><p>Au début, ne cherchez pas le prompt parfait. Partez de votre expression la plus naturelle. Comme si vous décriviez le besoin à un collègue, dites à l&#39;IA en langage courant ce que vous voulez faire, puis laissez l&#39;IA vous aider à optimiser en une expression plus professionnelle.</p><h4 id="_2-1-1-commencer-par-l-oral-recommande-pour-les-debutants" tabindex="-1">2.1.1 Commencer par l&#39;oral (recommandé pour les débutants) <a class="header-anchor" href="#_2-1-1-commencer-par-l-oral-recommande-pour-les-debutants" aria-label="Permalink to “2.1.1 Commencer par l&#39;oral (recommandé pour les débutants)”">​</a></h4><p>Décrivez d&#39;abord votre idée dans vos propres mots, même si c&#39;est très brut :</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Je veux créer un outil pour aider les opérationnels e-commerce à générer automatiquement des images principales et des textes de produits.</span></span>
<span class="line"><span>Les opérationnels doivent actuellement créer les images et textes un par un manuellement, c&#39;est très pénible.</span></span>
<span class="line"><span>Mon idée : ils uploadent les informations produit, le système génère un lot de brouillons,</span></span>
<span class="line"><span>et les opérationnels sélectionnent ceux qui sont bons, les modifient légèrement et les utilisent.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Pour commencer, la version la plus simple : une seule page, à gauche on remplit les infos produit,</span></span>
<span class="line"><span>à droite on affiche les résultats générés. On peut uploader des images, saisir du texte,</span></span>
<span class="line"><span>et après génération on voit l&#39;aperçu de l&#39;image principale et le texte.</span></span></code></pre></div><p>Ensuite, envoyez ce texte à une IA (comme ChatGPT, Claude, etc.) pour qu&#39;elle vous aide à l&#39;enrichir. L&#39;IA vous aidera généralement à combler des détails auxquels vous n&#39;aviez pas pensé, et à structurer votre idée plus clairement, pour finalement générer un prompt adapté à l&#39;IDE AI.</p><p>Vous pouvez dire à l&#39;IA :</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Aide-moi à enrichir l&#39;idée ci-dessus, organise-la en un document de logique métier clair,</span></span>
<span class="line"><span>puis génère un prompt adapté à un IDE AI (comme Cursor, Trae) pour générer le code d&#39;un prototype mono-page.</span></span></code></pre></div><p>L&#39;IA retournera un besoin structuré et le prompt correspondant. Vérifiez-le vous-même, supprimez les fonctionnalités inutiles, et une fois confirmé, utilisez-le pour générer le code.</p><p>L&#39;avantage de cette approche : l&#39;expression orale est l&#39;idée la plus authentique, mais peut manquer des détails importants. Quand l&#39;IA enrichit, elle peut poser des questions comme « voulez-vous supporter l&#39;upload par lot ? » que vous n&#39;aviez pas envisagées, vous aidant à valider davantage. Vous pouvez choisir de conserver ou supprimer les fonctionnalités non essentielles en fonction des retours, et déterminer le prompt initial pour l&#39;IA après plusieurs révisions.</p><h4 id="_2-1-2-passer-l-etape-d-enrichissement-envoyer-directement-votre-document-metier-a-l-ia" tabindex="-1">2.1.2 Passer l&#39;étape d&#39;enrichissement : envoyer directement votre document métier à l&#39;IA <a class="header-anchor" href="#_2-1-2-passer-l-etape-d-enrichissement-envoyer-directement-votre-document-metier-a-l-ia" aria-label="Permalink to “2.1.2 Passer l&#39;étape d&#39;enrichissement : envoyer directement votre document métier à l&#39;IA”">​</a></h4><p>Si vous avez déjà préparé un document de logique métier dans les chapitres précédents (par exemple, un cahier des charges en langage courant), vous pouvez directement utiliser le format suivant pour l&#39;envoyer à l&#39;IDE AI, en sautant l&#39;étape d&#39;enrichissement. Adapté quand le besoin est déjà clair et que vous voulez passer directement au code :</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Aide-moi à implémenter une application mono-page en te référant à la logique métier, pour valider la fonctionnalité clé.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>La logique métier de référence est la suivante :</span></span>
<span class="line"><span>1. Aider les opérationnels à générer en masse une première version de brouillons images/textes :</span></span>
<span class="line"><span>- **Entrée (supporte l&#39;upload direct et l&#39;import par lot de contenus) :**</span></span>
<span class="line"><span>  - Informations de base produit : nom, catégorie, marque, matière, taille, couleur, public cible, etc. ;</span></span>
<span class="line"><span>  - Images produit : image fond blanc / photo situation simple ;</span></span>
<span class="line"><span>  - Chaque génération supporte l&#39;upload supplémentaire de captures de produits best-sellers ou liens de référence, permettant d&#39;avoir des références ;</span></span>
<span class="line"><span>  - Supporte l&#39;import par lot via Excel, ou la saisie en ligne / upload sur la page.</span></span>
<span class="line"><span>  - Supporte la spécification sur la page pour sauvegarder ou non les contenus dans la bibliothèque, pour réutilisation</span></span>
<span class="line"><span>- **Sortie (contenu directement publiable ou publiable après légères modifications) :**</span></span>
<span class="line"><span>  - Pour chaque produit, une image principale brouillon « présentable, contenant les points de vente de base » ;</span></span>
<span class="line"><span>  - Un titre « bien structuré, contenant les mots-clés clés » + 1-2 phrases de texte de vente.</span></span>
<span class="line"><span>- **Changement d&#39;usage attendu :**</span></span>
<span class="line"><span>  Passer de la création de zéro pour chaque lot de produits à l&#39;envoi d&#39;un lot au système, puis sélection et ajustement des brouillons générés.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Faire d&#39;abord la première fonctionnalité, la deuxième (bibliothèque de modèles) sera ajoutée plus tard.</span></span></code></pre></div><h4 id="_2-1-3-l-approche-programmeur-avance-laisser-l-ia-ecrire-le-«-prompt-de-prompt-»" tabindex="-1">2.1.3 L&#39;approche programmeur (avancé) : laisser l&#39;IA écrire le « prompt de prompt » <a class="header-anchor" href="#_2-1-3-l-approche-programmeur-avance-laisser-l-ia-ecrire-le-«-prompt-de-prompt-»" aria-label="Permalink to “2.1.3 L&#39;approche programmeur (avancé) : laisser l&#39;IA écrire le « prompt de prompt »”">​</a></h4><p>Si vous voulez contrôler plus finement le processus de génération de code, vous pouvez d&#39;abord demander à une IA (comme ChatGPT) de générer, à partir de votre besoin, un prompt spécialement conçu pour l&#39;IDE AI :</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>En te basant sur l&#39;idée ci-dessous, aide-moi à écrire un prompt pour un Agent de codage,</span></span>
<span class="line"><span>j&#39;ai besoin de ce prompt pour générer du code.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[Colle ici ta description de logique métier]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Exigences :</span></span>
<span class="line"><span>1. Le prompt doit contenir une description claire de la mise en page</span></span>
<span class="line"><span>2. Préciser la structure de données et la logique d&#39;interaction</span></span>
<span class="line"><span>3. Spécifier la stack technique (ex : React + Tailwind)</span></span>
<span class="line"><span>4. Lister les points fonctionnels clés à implémenter</span></span></code></pre></div><p>L&#39;IA générera généralement un prompt structuré comme suit : <img src="`+b+'" alt=""></p><p>Vous pouvez modifier légèrement ce prompt avant de l&#39;envoyer à l&#39;IDE AI pour générer le code.</p><h3 id="_2-2-deuxieme-etape-laisser-l-ide-ai-generer-directement-le-code" tabindex="-1">2.2 Deuxième étape : laisser l&#39;IDE AI générer directement le code <a class="header-anchor" href="#_2-2-deuxieme-etape-laisser-l-ide-ai-generer-directement-le-code" aria-label="Permalink to “2.2 Deuxième étape : laisser l&#39;IDE AI générer directement le code”">​</a></h3><h4 id="_2-2-1-preparation-comprendre-les-operations-de-base-de-l-ide-ai" tabindex="-1">2.2.1 Préparation : comprendre les opérations de base de l&#39;IDE AI <a class="header-anchor" href="#_2-2-1-preparation-comprendre-les-operations-de-base-de-l-ide-ai" aria-label="Permalink to “2.2.1 Préparation : comprendre les opérations de base de l&#39;IDE AI”">​</a></h4><p>Si vous n&#39;êtes pas encore familier avec l&#39;utilisation basique de l&#39;IDE AI (comme Cursor, Trae, Windsurf, etc.), il est recommandé de consulter d&#39;abord le <a href="/easy-vibe-ja-learning-map/zh-cn/appendix/2-development-tools/ide-basics/">tutoriel de base sur l&#39;IDE</a> en annexe, pour apprendre comment :</p><ul><li>Créer un nouveau projet</li><li>Dialoguer avec l&#39;AI Agent</li><li>Comprendre le processus de génération de code de l&#39;IA</li></ul><h4 id="_2-2-2-commencer-a-generer-le-code" tabindex="-1">2.2.2 Commencer à générer le code <a class="header-anchor" href="#_2-2-2-commencer-a-generer-le-code" aria-label="Permalink to “2.2.2 Commencer à générer le code”">​</a></h4><p>Vous avez maintenant obtenu le prompt initial. Prenons le premier style de prompt comme exemple, et laissons l&#39;IA nous aider à générer le code. Créez d&#39;abord une fenêtre et le dossier correspondant, et ouvrez le dossier (initialisez un nouveau projet à l&#39;emplacement de votre choix) : <img src="'+f+'" alt=""><img src="'+h+'" alt=""></p><p>Dans la barre latérale, choisissez un modèle que vous aimez (recommandé : gemini, gpt, glm, kimi, minimax, etc.), et saisissez le prompt obtenu à la première étape : <img src="'+q+'" alt=""></p><p>Après avoir cliqué sur Générer, nous verrons une séquence familière : l&#39;IA va planifier la structure de répertoires du projet, les fichiers nécessaires, et donner le contenu initial de chaque fichier.</p><div class="warning custom-block"><p class="custom-block-title">⚠️ Attention particulière : l&#39;IA peut s&#39;arrêter et attendre votre confirmation</p><p>Pendant la génération, l&#39;AI Agent <strong>s&#39;arrête souvent pour attendre votre saisie ou confirmation</strong>, par exemple :</p><ul><li>Vous demander si vous voulez passer à l&#39;étape suivante</li><li>Vous demander d&#39;appuyer sur Entrée pour confirmer une action</li><li>Vous demander un choix sur un détail technique</li></ul><p><strong>Si vous voyez que l&#39;IA ne bouge plus, vérifiez d&#39;abord l&#39;interface de chat pour voir si elle attend votre réponse.</strong> Beaucoup de débutants pensent que l&#39;IA est en train de réfléchir, alors qu&#39;elle s&#39;est arrêtée pour les attendre. Répondez activement ou appuyez sur Entrée, et l&#39;IA reprendra son travail.</p></div><p>N&#39;oubliez pas non plus d&#39;appuyer sur Entrée pour confirmer (sinon vous resterez bloqué en attente — certains IDE AI ne rencontrent pas ce problème) : <img src="'+x+'" alt=""></p><p>Si vous rencontrez le scénario suivant, cela signifie qu&#39;un service local a déjà été démarré. Vous devez cliquer pour passer, sinon vous resterez sur cet écran (si rien ne s&#39;affiche après la génération du code, vous devrez dire activement « aide-moi à démarrer ce projet ») : <img src="'+y+'" alt=""></p><div class="info custom-block"><p class="custom-block-title">💡 Explication du scénario</p><p><strong>Explication du scénario</strong> : vous avez créé un projet React + TypeScript avec <code>npm create vite@latest</code> (easy-vibe-web). Une fois la création terminée, l&#39;ordinateur va automatiquement « lancer » la page web, pour que vous puissiez voir le résultat immédiatement.</p><p><strong>Service local</strong> : on peut comprendre ça comme une fenêtre d&#39;affichage web temporaire ouverte sur votre ordinateur, qui ne fonctionne que sur cette machine — les autres n&#39;y ont pas accès.</p><p><strong>localhost (adresse locale)</strong> : <code>localhost</code> signifie « cet ordinateur lui-même ». Quand le navigateur y accède, il accède en fait à la page web exécutée sur votre ordinateur.</p><p><strong>Port</strong> : le port est un numéro utilisé pour distinguer les différents services web sur le même ordinateur. Ce projet utilise le port 5174.</p><p><strong>Lien d&#39;accès <code>http://localhost:5174/</code></strong> : cette adresse signifie « accéder à la page web numéro 5174 sur cet ordinateur ». Ouvrez-la dans le navigateur pour voir le résultat.</p><p><strong>Explication de ce scénario</strong> : le système voulait initialement utiliser le port 5173, mais celui-ci était déjà occupé, donc il a automatiquement basculé vers 5174 — c&#39;est normal.</p><p><strong>Instructions</strong> : ouvrez le navigateur, tapez <code>http://localhost:5174/</code> dans la barre d&#39;adresse et appuyez sur Entrée pour voir la page du projet actuel.</p></div><p>Une fois toutes les confirmations terminées, attendez que l&#39;agent s&#39;exécute quelques instants, et vous obtiendrez le résultat suivant : <img src="'+A+'" alt=""></p><p>On peut voir qu&#39;il y a déjà une première version fonctionnelle, mais la page frontend est vraiment laide. À ce stade, vous pouvez essayer de dialoguer directement avec l&#39;IA pour optimiser l&#39;affichage de l&#39;interface : <img src="'+I+'" alt=""></p><p>Après optimisation, nous obtenons une interface plus esthétique : <img src="'+_+'" alt=""></p><p>Vous pouvez modifier les fonctionnalités de la page selon vos besoins, joindre des captures d&#39;écran et poser des questions librement, par exemple : « Je n&#39;ai pas besoin de la fonctionnalité d&#39;import par lot pour l&#39;instant, aide-moi à la supprimer », « Il y a trop de champs à remplir à gauche, garde uniquement xxxxx ». Vous pouvez même vous référer à d&#39;autres sites matures — par exemple, vous pouvez directement « vous inspirer » d&#39;un produit de design de Google (vous pouvez coller une capture d&#39;écran d&#39;un site mature que vous aimez) : <img src="'+k+'" alt=""></p><p>Et finalement obtenir : <img src="'+z+'" alt=""></p><h3 id="_2-3-que-faire-en-cas-d-erreur" tabindex="-1">2.3 Que faire en cas d&#39;erreur <a class="header-anchor" href="#_2-3-que-faire-en-cas-d-erreur" aria-label="Permalink to “2.3 Que faire en cas d&#39;erreur”">​</a></h3><p>En pratique, rencontrer des erreurs est inévitable — c&#39;est normal et ne signifie pas que vous avez fait quelque chose de mal. Vous n&#39;avez pas besoin de comprendre l&#39;erreur ; il suffit de transmettre la « situation observée » en entier à l&#39;IA.</p><p>Il n&#39;y a que trois approches courantes :</p><ul><li><p><strong>Approche 1 : Erreur sur la page ou le terminal</strong> Quand la page devient rouge, affiche un écran blanc, ou quand le terminal affiche un tas de texte rouge, faites une capture d&#39;écran ou copiez l&#39;intégralité du message d&#39;erreur et envoyez-le à l&#39;IA pour qu&#39;elle vous aide à réparer.</p></li><li><p><strong>Approche 2 : La fonctionnalité ne fonctionne pas mais pas d&#39;erreur</strong> Par exemple, un bouton ne réagit pas, les données ne s&#39;affichent pas, les styles sont cassés — décrivez en langage courant « ce qui se passe + ce que vous vouliez », en ajoutant une capture d&#39;écran si nécessaire.</p></li><li><p><strong>Approche 3 : Vous n&#39;êtes pas sûr s&#39;il y a un problème</strong> Vous pouvez demander directement à l&#39;IA : « Aide-moi à vérifier si cette fonctionnalité a des problèmes évidents, est-ce qu&#39;il faut ajuster quelque chose. »</p></li></ul><h4 id="_2-3-1-questions-frequentes-des-debutants" tabindex="-1">2.3.1 Questions fréquentes des débutants <a class="header-anchor" href="#_2-3-1-questions-frequentes-des-debutants" aria-label="Permalink to “2.3.1 Questions fréquentes des débutants”">​</a></h4><ul><li><p><strong>Q : Je ne sais pas où trouver le message d&#39;erreur ?</strong></p></li><li><p>R : En général, cherchez tout le « texte rouge ». Dans le terminal, la console ou sur la page, trouvez les indications rouges, sélectionnez tout et copiez pour l&#39;IA.</p></li><li><p><strong>Q : L&#39;IA a corrigé mais l&#39;erreur persiste ?</strong></p></li><li><p>R : C&#39;est courant. Continuez à faire une capture d&#39;écran ou copiez le dernier message d&#39;erreur et envoyez-le, pour qu&#39;elle corrige davantage sur la base de la modification précédente.</p></li><li><p><strong>Q : Dois-je comprendre complètement la solution de réparation de l&#39;IA ?</strong></p></li><li><p>R : Non, pas besoin de tout comprendre d&#39;un coup. Vous pouvez vous concentrer sur un ou deux points à chaque fois. Avec le temps, vous comprendrez de plus en plus de code, comme en accumulant du vocabulaire anglais.</p></li><li><p><strong>Q : J&#39;ai corrigé plein de fois, le problème persiste ?</strong></p></li><li><p>R : Vous pouvez essayer :</p><ul><li>Utiliser la fonction « retour en arrière » de l&#39;IDE, trouver le bouton de retour dans la conversation de l&#39;agent, revenir à une version fonctionnelle et recommencer ;</li><li>Changer de modèle ou ajuster le prompt, décrire le phénomène et le message d&#39;erreur plus précisément ;</li><li>Regrouper « code actuel + log d&#39;erreurs + comportement attendu » et tout envoyer d&#39;un coup à l&#39;IA, pour qu&#39;elle restructure globalement la partie problématique.</li></ul></li></ul><h2 id="_3-passer-d-une-application-mono-page-a-une-application-multi-pages" tabindex="-1">3. Passer d&#39;une application mono-page à une application multi-pages <a class="header-anchor" href="#_3-passer-d-une-application-mono-page-a-une-application-multi-pages" aria-label="Permalink to “3. Passer d&#39;une application mono-page à une application multi-pages”">​</a></h2>',45)),e("div",M,[t(l,null,{default:r(()=>[t(o,{active:2,items:[{title:"Analyse des besoins",description:"Du flou au concret"},{title:"Validation mono-page",description:"Fonctionnalité clé implémentée"},{title:"Extension multi-pages",description:"Structure d'application complète"},{title:"Peaufinage",description:"Amélioration de l'expérience utilisateur"}]})]),_:1})]),s[11]||(s[11]=a('<p>Une fois la logique de la fonctionnalité clé générée, nous pouvons générer le reste du contenu. Par exemple, à ce stade, si vous cliquez sur Paramètres ou certains boutons, ils ne fonctionnent pas du tout.</p><p>Vous pouvez demander à l&#39;IA de vérifier selon les besoins du prompt métier, de générer les parties manquantes, ou de compléter directement les pages non implémentées. Vous pouvez aussi spécifier une page pour que l&#39;IA la complète, jusqu&#39;à ce que toutes les pages soient cliquables et que les fonctionnalités soient interactives : <img src="'+P+'" alt=""></p><p>Après quelques instants, nous pouvons voir que le programme a complété plusieurs pages et fonctionnalités interactives sur la base de ce qui existait déjà : <img src="'+C+'" alt=""></p><p><img src="'+E+'" alt=""></p><p>Il vous suffit alors de cliquer manuellement sur chaque fonctionnalité et bouton qui vous intéresse, pour vous assurer que les interactions sont normales. Si une fonctionnalité n&#39;est pas interactive, vous pouvez en parler avec l&#39;IA pour qu&#39;elle vous aide à la corriger.</p><h2 id="_4-rendre-le-prototype-«-convaincant-»" tabindex="-1">4. Rendre le prototype « convaincant » <a class="header-anchor" href="#_4-rendre-le-prototype-«-convaincant-»" aria-label="Permalink to “4. Rendre le prototype « convaincant »”">​</a></h2>',6)),e("div",O,[t(l,null,{default:r(()=>[t(o,{active:3,items:[{title:"Analyse des besoins",description:"Du flou au concret"},{title:"Validation mono-page",description:"Fonctionnalité clé implémentée"},{title:"Extension multi-pages",description:"Structure d'application complète"},{title:"Peaufinage",description:"Amélioration de l'expérience utilisateur"}]})]),_:1})]),s[12]||(s[12]=a(`<p>Une fois la structure multi-pages en place, la dernière étape consiste à faire passer le prototype de « ça fonctionne » à « c&#39;est fluide à utiliser et ça a l&#39;air pro ». Cela nécessite de tester manuellement tout le flux (parcours utilisateur), et de faire corriger par l&#39;IA les parties qui ne fonctionnent pas, pour qu&#39;à chaque rafraîchissement on puisse simuler un nouvel utilisateur parcourant tout le flux et obtenir le résultat attendu.</p><p>Revenons au besoin initial :</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>1. Aider les opérationnels à générer en masse une première version de brouillons images/textes :</span></span>
<span class="line"><span>- **Entrée (supporte l&#39;upload direct et l&#39;import par lot de contenus) :**</span></span>
<span class="line"><span>  - Informations de base produit : nom, catégorie, marque, matière, taille, couleur, public cible, etc. ;</span></span>
<span class="line"><span>  - Images produit : image fond blanc / photo situation simple ;</span></span>
<span class="line"><span>  - Chaque génération supporte l&#39;upload supplémentaire de captures de produits best-sellers ou liens de référence ;</span></span>
<span class="line"><span>  - Supporte l&#39;import par lot via Excel, ou la saisie en ligne / upload sur la page.</span></span>
<span class="line"><span>  - Supporte la spécification sur la page pour sauvegarder ou non les contenus dans la bibliothèque</span></span>
<span class="line"><span>- **Sortie (contenu directement publiable ou après légères modifications) :**</span></span>
<span class="line"><span>  - Pour chaque produit, une image principale brouillon « présentable, contenant les points de vente de base » ;</span></span>
<span class="line"><span>  - Un titre « bien structuré, contenant les mots-clés clés » + 1-2 phrases de texte de vente.</span></span>
<span class="line"><span>- **Changement d&#39;usage attendu :**</span></span>
<span class="line"><span>  Passer de la création de zéro pour chaque lot de produits à l&#39;envoi d&#39;un lot au système, puis sélection et ajustement des brouillons générés.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>2. Capitaliser les bonnes sorties en une bibliothèque de modèles réutilisables :</span></span>
<span class="line"><span>- **Que peut-on sauvegarder ?**</span></span>
<span class="line"><span>  - Toute sortie que l&#39;opérationnel juge « bonne » peut être sauvegardée en un clic :</span></span>
<span class="line"><span>    - Ça peut être la combinaison complète « image principale + titre + texte de vente » ;</span></span>
<span class="line"><span>    - Ou seulement une partie, comme une structure de titre ou un texte de vente spécifique.</span></span>
<span class="line"><span>- **Que peut-on faire après sauvegarde ?**</span></span>
<span class="line"><span>  - **Réutiliser :**</span></span>
<span class="line"><span>    - Utiliser cette sauvegarde pour appliquer un lot de nouveaux paramètres produit, et régénérer des brouillons images/textes ;</span></span>
<span class="line"><span>    - Ou sur le même produit, générer plusieurs variantes basées sur ce modèle pour des tests A/B.</span></span>
<span class="line"><span>  - **Éditer :**</span></span>
<span class="line"><span>    - Modifier directement le titre / texte de vente ;</span></span>
<span class="line"><span>    - Si l&#39;édition d&#39;images est supportée, affiner le texte, les stickers, etc. sur l&#39;image principale.</span></span>
<span class="line"><span>  - **Gérer :**</span></span>
<span class="line"><span>    - Nommer les sauvegardes, étiqueter (ex : « modèle image principale sac homme », « structure titre promo »), classer par boutique pour faciliter la recherche.</span></span>
<span class="line"><span>- **Comment utiliser lors de la prochaine mise en ligne ?**</span></span>
<span class="line"><span>  - Après import de nouveaux produits, l&#39;opérationnel peut choisir :</span></span>
<span class="line"><span>    - Utiliser la logique par défaut du système, ou</span></span>
<span class="line"><span>    - Spécifier « utiliser un de mes modèles sauvegardés pour générer » ;</span></span>
<span class="line"><span>  - Le système applique automatiquement la structure et le style du modèle aux nouvelles données produit, et génère de nouveaux brouillons image principale + titre + texte de vente.</span></span></code></pre></div><p>Si vous devez créer de nouvelles données à chaque test, cela prend beaucoup de temps. C&#39;est là qu&#39;on utilise généralement ce qu&#39;on appelle des « données de test ». Vous pouvez communiquer avec l&#39;IA de la façon suivante, pour qu&#39;elle génère une entrée rapide de données de test sur l&#39;interface, pour que nous puissions vérifier que toutes les fonctionnalités fonctionnent correctement :</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>J&#39;ai besoin de tester ce parcours utilisateur pour m&#39;assurer qu&#39;il fonctionne complètement.</span></span>
<span class="line"><span>Merci de générer une entrée de données de test en te basant sur les besoins suivants,</span></span>
<span class="line"><span>pour que je puisse cliquer et tester rapidement si le flux complet fonctionne normalement :</span></span>
<span class="line"><span>1. Aider les opérationnels à générer en masse une première version de brouillons images/textes :</span></span>
<span class="line"><span>- **Entrée (supporte l&#39;upload direct et l&#39;import par lot de contenus) :**</span></span>
<span class="line"><span>  - Informations de base produit : nom, catégorie, marque, matière, taille, couleur, public cible, etc. ;</span></span>
<span class="line"><span>  - Images produit : image fond blanc / photo situation simple ;</span></span>
<span class="line"><span>  - Chaque génération supporte l&#39;upload supplémentaire de captures de produits best-sellers ou liens de référence ;</span></span>
<span class="line"><span>  - Supporte l&#39;import par lot via Excel, ou la saisie en ligne / upload sur la page.</span></span>
<span class="line"><span>  - Supporte la spécification sur la page pour sauvegarder ou non les contenus dans la bibliothèque</span></span>
<span class="line"><span>- **Sortie (contenu directement publiable ou après légères modifications) :**</span></span>
<span class="line"><span>  - Pour chaque produit, une image principale brouillon « présentable, contenant les points de vente de base » ;</span></span>
<span class="line"><span>  - Un titre « bien structuré, contenant les mots-clés clés » + 1-2 phrases de texte de vente.</span></span>
<span class="line"><span>- **Changement d&#39;usage attendu :**</span></span>
<span class="line"><span>  Passer de la création de zéro pour chaque lot de produits à l&#39;envoi d&#39;un lot au système, puis sélection et ajustement des brouillons générés.</span></span></code></pre></div><p>On obtient facilement le résultat (si vous trouvez qu&#39;une donnée c&#39;est trop peu, vous pouvez demander à l&#39;IA de générer plusieurs cas de test) : <img src="`+S+'" alt=""></p><p>Résultat après clic : <img src="'+D+'" alt=""></p><p>À ce stade, nous obtenons directement le résultat, sans qu&#39;il y ait un « processus de génération simulé ». Si nous voulons simuler un vrai processus de génération, nous pouvons directement parler à l&#39;IA : « Merci de simuler un vrai processus de génération, il faut attendre un moment après le clic avant de me donner le résultat. » <img src="'+T+'" alt=""></p><p>Une fois la fonctionnalité de génération validée, nous devons aussi nous assurer que la fonctionnalité de bibliothèque de modèles fonctionne correctement. Sur la carte de génération de la page, nous pouvons voir que la fonctionnalité de favoris de la bibliothèque de modèles n&#39;est pas implémentée. Il faut alors approfondir la conversation avec l&#39;IA : « Merci de t&#39;assurer que le besoin [collez ici le contenu du point 2 ci-dessus] fonctionne correctement, on peut cliquer sur un résultat pour sauvegarder le modèle correspondant, et en l&#39;ouvrant on peut voir les paramètres de génération »</p><p>La génération n&#39;est souvent pas immédiate, il faut régulièrement corriger avec des captures d&#39;écran : <img src="'+j+'" alt=""></p><p>Et finalement obtenir le résultat attendu : <img src="'+V+'" alt=""></p><p>En plus du test manuel du parcours des besoins, vous pouvez aussi demander à l&#39;IA de faire directement une vérification des besoins, par exemple :</p><ul><li>« Merci de vérifier par rapport à mon besoin initial si l&#39;application actuelle couvre toutes les fonctionnalités clés. »</li><li>« Aide-moi à lister un checklist des fonctionnalités, en indiquant lesquelles sont terminées, lesquelles ne sont pas encore implémentées ou ont une expérience insuffisante. »</li></ul><p>L&#39;IA générera généralement un checklist, à partir duquel vous pouvez décider s&#39;il faut continuer à améliorer. Après des modifications itératives, vous obtiendrez un prototype assez abouti.</p><h2 id="_5-📚-exercice-reproduisez-votre-propre-atelier-de-contenus-tiktok-e-commerce" tabindex="-1">5. 📚 Exercice : reproduisez votre propre atelier de contenus TikTok e-commerce <a class="header-anchor" href="#_5-📚-exercice-reproduisez-votre-propre-atelier-de-contenus-tiktok-e-commerce" aria-label="Permalink to “5. 📚 Exercice : reproduisez votre propre atelier de contenus TikTok e-commerce”">​</a></h2>',15)),t(u,{shadow:"hover",style:{margin:"20px 0","border-radius":"12px"}},{header:r(()=>[...s[2]||(s[2]=[e("div",{style:{"font-weight":"bold","font-size":"16px"}},"🚀 Défi : reproduire l'atelier de contenus e-commerce",-1)])]),default:r(()=>[s[3]||(s[3]=e("p",null," En vous référant aux prompts et au contenu de ce cours, réalisez un cycle complet : ",-1)),s[4]||(s[4]=e("ul",null,[e("li",null,[e("strong",null,"Pratique du cycle complet"),e("ul",null,[e("li",null,"Génération de prompt de synthèse métier → génération de prototype mono-page → génération de prototype multi-pages")])]),e("li",null,[e("strong",null,"Partage des résultats"),e("ul",null,[e("li",null,"Faites une capture d'écran de votre programme et partagez-la avec tout le monde")])]),e("li",null,[e("strong",null,"Question de réflexion"),e("ul",null,[e("li",null,"Réservez de l'espace pour la prochaine section « Intégration des capacités LLM et de génération d'images à partir de texte », et anticipez : comment votre atelier pourrait-il intégrer des capacités comme « IA écrit le texte / génère les images / génère le script » ?")])])],-1))]),_:1}),s[13]||(s[13]=e("h2",{id:"prochaine-etape",tabindex:"-1"},[n("Prochaine étape "),e("a",{class:"header-anchor",href:"#prochaine-etape","aria-label":"Permalink to “Prochaine étape”"},"​")],-1)),s[14]||(s[14]=e("p",null,"Dans la section suivante, nous construirons sur cet atelier de production de contenus en y intégrant des capacités AI spécifiques (texte vers texte, image vers texte, texte vers image), par exemple :",-1)),s[15]||(s[15]=e("ul",null,[e("li",null,"Générer automatiquement des brouillons de textes et plusieurs propositions de titres pour une tâche de contenu"),e("li",null,"Générer automatiquement des brouillons d'images à partir de la description de la tâche (texte vers image)"),e("li",null,"Classer et résumer automatiquement les tâches de contenu passées, pour vous aider à planifier les sujets de la prochaine promotion")],-1)),t(m,{title:"Continuer à apprendre",description:"Il est recommandé de continuer dans l'ordre : intégrer les capacités AI → cycle complet du projet → ingénierie du design.",items:L(d)},null,8,["items"])])}}});export{J as __pageData,W as default};
